// === Tab: mySketch.js ===
let vmin, vmax;
let tex;
let gl, glsl;
let camera;
let BPM = 144;
let NUM_LIGHTS = 8;
let overTex;
let mx, my, me = 0.01;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1353274/files/shader.vert', 'shader.frag');
}

function setup() {
  createCanvas(1112, 834);
  smooth();
  noStroke();
  vmin = (width < height) ? width : height;
  vmax = (width > height) ? width : height;
  mx = width / 2;
  my = height / 2;
  tex = createGraphics(width, height, WEBGL);
  tex.noStroke();
  gl = tex.drawingContext;
  camera = tex.createCamera();
  camera.perspective((90 / 180) * PI, width / height, 0.1, vmax * 5);
  camera.setPosition(0, -vmin * 0.25, vmin * 0.75);
  camera.lookAt(0, 0, 0);

  overTex = createGraphics(width, height);
  overTex.noStroke();
  for (let i = 0; i < (overTex.width * overTex.height) / 5; i++) {
    let x = random(overTex.width);
    let y = random(overTex.height);
    let a = floor(random(20)) * 8 + 8;
    overTex.fill(0, a);
    overTex.square(x, y, 1);
  }
}

function volumeSpot(x, y, z, size) {
  tex.push();
  {
    tex.translate(x, y - size, z);
    tex.rotateX(PI);
    tex.push();
    {
      let N = 60;
      let radius = vmin * 0.1125;
      tex.translate(0, -size / 2, 0);
      for (let i = 0; i < N; i++) {
        let ni = (i / (N - 1));
        let r = pow(ni, 2) * radius;
        tex.fill(0, 220, 0, 10 * (1.0 - ni) + 4);
        tex.cone(r, size, 24, 1, false);
      }
    }
    tex.pop();
  }
  tex.pop();
}

function drawScene() {
  let sec = millis() / 1000;
  let size = vmin;
  var r = vmin * 0.5;

  mx += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mx) * me;
  my += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - my) * me;
  let rx = map(my, 0, tex.width, -0.25, 0.25) * PI;
  let ry = map(mx, 0, tex.width, 0.3, -0.3) * PI;

  tex.clear(0);
  tex.background(0);

  tex.push();
  {
    tex.rotateX(rx);
    tex.rotateY(ry);

    let posArr = [];
    for (let i = 0; i < NUM_LIGHTS; i++) {
      var a = i * (TWO_PI / NUM_LIGHTS) - HALF_PI;
      var x = cos(a) * r;
      var y = 0;
      let z = sin(a) * r;
      posArr.push({ x, y, z });
    }

    tex.push();
    {
      tex.translate(0, 0, 0);
      tex.rotateX(PI / 2);
      tex.noStroke();
      tex.fill(255);
      tex.shader(glsl);
      glsl.setUniform('uColor', [1.0, 0.0, 0.0]);
      for (let i = 0; i < NUM_LIGHTS; i++) {
        var x = map(posArr[i].x, -vmax, vmax, 0, 1);
        var z = map(posArr[i].z, -vmax, vmax, 0, 1);
        glsl.setUniform(`uPos${ i }`, [x, z]);
      }
      tex.plane(vmax * 2, vmax * 2);
    }
    tex.pop();

    tex.noLights();
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE);

		posArr.sort((a, b) => {
			let ad = dist(camera.eyeX, camera.eyeZ, a.x, a.z);
			let bd = dist(camera.eyeX, camera.eyeZ, b.x, b.z);
			return bd - ad;
		});
		for (let { x, y, z } of posArr) {
			volumeSpot(x, y, z, size);
		}

		gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
  }
  tex.pop();
}

function draw() {
  drawScene();

  image(tex, 0, 0);
  image(overTex, 0, 0);
}

// === Tab: shader.frag ===
precision highp float;

varying vec2 vTexCoord;

uniform vec3 uColor;
uniform vec2 uPos0;
uniform vec2 uPos1;
uniform vec2 uPos2;
uniform vec2 uPos3;
uniform vec2 uPos4;
uniform vec2 uPos5;
uniform vec2 uPos6;
uniform vec2 uPos7;

void main() {
  vec2 uv = vTexCoord;

  float lightMask = 0.;
  if (uPos0.x != 0. && uPos0.y != 0.) {
    float d0 = 0.065 / length(uv - uPos0);
    d0 = pow(d0, 2.0);
    lightMask += d0;
  }
  if (uPos1.x != 0. && uPos1.y != 0.) {
    float d1 = 0.065 / length(uv - uPos1);
    d1 = pow(d1, 2.0);
    lightMask += d1;
  }
  if (uPos2.x != 0. && uPos2.y != 0.) {
    float d2 = 0.065 / length(uv - uPos2);
    d2 = pow(d2, 2.0);
    lightMask += d2;
  }
  if (uPos3.x != 0. && uPos3.y != 0.) {
    float d3 = 0.065 / length(uv - uPos3);
    d3 = pow(d3, 2.0);
    lightMask += d3;
  }
  if (uPos4.x != 0. && uPos4.y != 0.) {
    float d4 = 0.065 / length(uv - uPos4);
    d4 = pow(d4, 2.0);
    lightMask += d4;
  }
  if (uPos5.x != 0. && uPos5.y != 0.) {
    float d5 = 0.065 / length(uv - uPos5);
    d5 = pow(d5, 2.0);
    lightMask += d5;
  }
  if (uPos6.x != 0. && uPos6.y != 0.) {
    float d6 = 0.065 / length(uv - uPos6);
    d6 = pow(d6, 2.0);
    lightMask += d6;
  }
  if (uPos7.x != 0. && uPos7.y != 0.) {
    float d7 = 0.075 / length(uv - uPos7);
    d7 = pow(d7, 2.0);
    lightMask += d7;
  }

  vec3 color = uColor * (lightMask * 0.1);

  gl_FragColor = vec4(color, 1.0);
}

// === Tab: shader.vert ===
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec3 aNormal;

uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 position = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * position;
}

